  if (isJsonArray(inp["edits"])) {
    const parts: string[] = [];

    for (const e of inp["edits"]) {
      if (!isJsonObject(e)) continue;

      let hunk = "";

      if (e["old_string"]) hunk += `REMOVED:\n${e["old_string"]}\n`;

      if (e["new_string"]) hunk += `ADDED:\n${e["new_string"]}`;

      if (hunk) parts.push(hunk);
    }

