  }

  const content = String(inp["content"] ?? inp["new_source"] ?? "");

  if (content && cwd && isString(inp["file_path"]) && inp["file_path"]) {
    return writeHunk(cwd, relativeTo(inp["file_path"], cwd), content);
  }

  return content;
